choose.when:
SELECT ro.source_type, ro.id order_id, xo.id channel_order_id, COALESCE(xo.external_order_id,ro.order_no) order_no, NULL device_id, NULL assignment_id, NULL device_no, (SELECT GROUP_CONCAT(DISTINCT i.equipment_model_code ORDER BY i.equipment_model_code SEPARATOR ' / ') FROM rental_order_item i WHERE i.rental_order_id=ro.id AND i.tenant_id=ro.tenant_id AND i.deleted=0) equipment_model_code, xo.goods_title, ro.preparation_status, ro.preparation_reason_code, (SELECT SUM(i.quantity) FROM rental_order_item i WHERE i.rental_order_id=ro.id AND i.tenant_id=ro.tenant_id AND i.deleted=0) required_quantity, EXISTS(SELECT 1 FROM rental_order_item i WHERE i.rental_order_id=ro.id AND i.tenant_id=ro.tenant_id AND i.deleted=0 AND i.quantity_source='LEGACY' AND i.quantity>1) quantity_needs_review, ro.occupy_start_date due_date FROM rental_order ro LEFT JOIN xianyu_order xo ON xo.id=ro.channel_order_id AND xo.tenant_id=ro.tenant_id AND xo.deleted=0 WHERE ro.tenant_id=#{tenantId} AND ro.deleted=0 AND ro.status NOT IN ('CANCELED','CANCELLED','COMPLETED')
AND ro.occupy_start_date = #{today} AND ro.occupy_start_date < #{today} AND ro.occupy_start_date <= #{today}
AND (ro.source_type != 'XIANYU' OR (xo.id IS NOT NULL AND xo.order_status='12' AND xo.consign_time IS NULL AND xo.cancel_time IS NULL AND COALESCE(xo.refund_status,0) != 5)) AND EXISTS(SELECT 1 FROM rental_order_item i WHERE i.rental_order_id=ro.id AND i.tenant_id=ro.tenant_id AND i.deleted=0 AND i.quantity > (SELECT COUNT(*) FROM rental_device_assignment a WHERE a.rental_order_item_id=i.id AND a.tenant_id=i.tenant_id AND a.deleted=0 AND a.status IN ('DISPATCHED','DISPATCHED_PENDING_PLAN','RETURNED')))
UNION ALL SELECT 'XIANYU' source_type, NULL order_id, xo.id channel_order_id, xo.external_order_id order_no, NULL device_id, NULL assignment_id, NULL device_no, NULL equipment_model_code, xo.goods_title, xo.preparation_status, COALESCE(xo.preparation_reason_code,xo.rental_period_reason_code) preparation_reason_code, NULL required_quantity, FALSE quantity_needs_review, xo.ship_date due_date FROM xianyu_order xo WHERE xo.tenant_id=#{tenantId} AND xo.deleted=0 AND xo.order_status='12' AND xo.consign_time IS NULL AND xo.cancel_time IS NULL AND COALESCE(xo.refund_status,0) != 5 AND NOT EXISTS(SELECT 1 FROM rental_order ro WHERE ro.channel_order_id=xo.id AND ro.tenant_id=xo.tenant_id AND ro.deleted=0)
AND xo.ship_date = #{today} AND xo.ship_date < #{today} AND xo.ship_date <= #{today}
